import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def check_solution(q):
    if not is_prime(q):
        return None

    target = q**2 - q + 1

    # Check if target is a perfect cube
    cbrt_val = round(target**(1/3))
    if cbrt_val**3 == target:
        p = cbrt_val
        if is_prime(p) and p != q:
            return p
        else:
            return None
    return None

# Check primes q up to 100
primes_to_check = [q for q in range(2, 101) if is_prime(q)]
solutions = {}
for q in primes_to_check:
    p = check_solution(q)
    if p is not None:
        solutions[q] = p

print(solutions)
